import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}`),a={name:`architecture.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h1><p>FaultDeck is a Rust workspace. The current implementation ships <strong>six built crates</strong> plus one empty placeholder (<code>faultdeck-protocol</code> — the directory exists but contains no <code>Cargo.toml</code> and is <strong>not</strong> a workspace member yet). The planned toxiproxy backend and scenario YAML DSL from the <a href="/faultdeck/design/mvp-plan.html">MVP plan</a> are not implemented; today&#39;s backend is <code>tc netem</code> + <code>iptables</code>.</p><h2 id="crates" tabindex="-1">Crates <a class="header-anchor" href="#crates" aria-label="Permalink to “Crates”">​</a></h2><table tabindex="0"><thead><tr><th>crate</th><th>binary</th><th>responsibility</th></tr></thead><tbody><tr><td><code>faultdeck-core</code></td><td>—</td><td>shared model: <code>FaultSpec</code> (latency / loss / disconnect), <code>Target</code>, <code>Injection</code>, intrinsic validation (<code>validate_injection</code>), management-network overlap check</td></tr><tr><td><code>faultdeck-netem</code></td><td>—</td><td><code>tc</code> adapter: plans and executes <code>tc qdisc</code>/<code>filter</code> commands, preflight checks, rollback, <code>dry_run</code> executor</td></tr><tr><td><code>faultdeck-agent</code></td><td><code>faultdeck-agent</code></td><td>resident TCP daemon: token auth, request handling, iptables firewall (disconnect), single-active-fault state</td></tr><tr><td><code>faultdeck-coordinator</code></td><td><code>faultdeck-coordinator</code></td><td>multi-target hub: agent registry (register/heartbeat/list with online status), report archive, live inject/rollback dispatch over agent reverse links, per-agent queues for offline agents</td></tr><tr><td><code>faultdeck-report</code></td><td>—</td><td><code>Scenario</code>, <code>RunReport</code> (JSON/HTML), SHA-256 scenario hash, <code>compare_runs</code> history diff</td></tr><tr><td><code>faultdeck-cli</code></td><td><code>faultdeck</code></td><td>CLI entry: <code>faultdeck remote ping / inject / rollback</code> (direct to agent) and <code>faultdeck hub list / inject / rollback</code> (via coordinator)</td></tr><tr><td><code>faultdeck-protocol</code></td><td>—</td><td><em>placeholder, not in workspace</em></td></tr></tbody></table><h2 id="interaction-overview" tabindex="-1">Interaction overview <a class="header-anchor" href="#interaction-overview" aria-label="Permalink to “Interaction overview”">​</a></h2><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> faultdeck CLI                faultdeck-agent                target host</span></span>
<span class="line"><span> ┌──────────────┐   TCP,      ┌──────────────────┐   tc      ┌──────────┐</span></span>
<span class="line"><span> │ remote ping  │──newline──▶ │ token auth       │──qdisc──▶ │  eth0    │</span></span>
<span class="line"><span> │ remote inject│   framed    │ mgmt-network guard│──filter─▶ │ (netem)  │</span></span>
<span class="line"><span> │ remote       │   JSON      │ validate_injection│           └──────────┘</span></span>
<span class="line"><span> │   rollback   │             │                  │  iptables ┌──────────┐</span></span>
<span class="line"><span> └──────────────┘             │ firewall (mangle)│──DROP────▶│ disconnect│</span></span>
<span class="line"><span>                              └──────────────────┘  -t mangle└──────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span> faultdeck-coordinator (default :7001)</span></span>
<span class="line"><span> ┌────────────────────────────────────────────┐</span></span>
<span class="line"><span> │ registry: agents / reports / links /       │◀── framed JSON lines (multi-message</span></span>
<span class="line"><span> │   queues                                   │    connections, threaded accept)</span></span>
<span class="line"><span> │ AgentCommand: register, heartbeat,         │◀── agent reverse links: RegisterEnvelope,</span></span>
<span class="line"><span> │   inject, rollback, fetch_report,          │    then LinkMessage::Dispatch → Result /</span></span>
<span class="line"><span> │   list_agents                              │    Heartbeat on the same connection</span></span>
<span class="line"><span> └────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="wire-protocol-cli-↔-agent" tabindex="-1">Wire protocol (CLI ↔ agent) <a class="header-anchor" href="#wire-protocol-cli-↔-agent" aria-label="Permalink to “Wire protocol (CLI ↔ agent)”">​</a></h2><p>One TCP connection per CLI invocation. The client sends a single line; the agent answers with a single JSON line and closes.</p><ul><li>With token: <code>&lt;token&gt; {json}\\n</code> — without: <code>{json}\\n</code></li><li>Request: <code>{&quot;cmd&quot;:&quot;ping&quot;}</code> | <code>{&quot;cmd&quot;:&quot;inject&quot;, ...Injection}</code> | <code>{&quot;cmd&quot;:&quot;rollback&quot;}</code></li><li>Response: <code>{&quot;status&quot;:&quot;ok&quot;,&quot;message&quot;:&quot;...&quot;}</code> | <code>{&quot;status&quot;:&quot;error&quot;,&quot;message&quot;:&quot;...&quot;}</code></li></ul><h2 id="wire-protocol-coordinator" tabindex="-1">Wire protocol (coordinator) <a class="header-anchor" href="#wire-protocol-coordinator" aria-label="Permalink to “Wire protocol (coordinator)”">​</a></h2><p>Long-lived connections, newline-framed JSON lines in both directions (<code>faultdeck-agent::transport</code>). One listener serves two session kinds, disambiguated by the first frame:</p><ul><li><strong>Controller session</strong> — a <code>WireMessage</code> envelope per command. <code>AgentCommand</code>: <code>register</code> | <code>heartbeat</code> | <code>inject</code> | <code>rollback</code> | <code>fetch_report</code> | <code>list_agents</code>; <code>AgentResponse</code>: <code>ok</code> | <code>error</code> | <code>registered</code> | <code>queued</code> | <code>agents</code> | <code>report</code>.</li><li><strong>Agent link</strong> — the agent dials the coordinator outbound (double-NAT safe) and sends a <code>RegisterEnvelope</code> first (<code>crates/agent/src/link.rs:46</code>); afterwards the coordinator writes <code>LinkMessage::Dispatch</code> frames down the same connection and the agent answers with <code>LinkMessage::Result</code> plus periodic <code>LinkMessage::Heartbeat</code>s.</li></ul><p>State lives in a <code>Mutex&lt;CoordinatorState&gt;</code>: <code>agents</code>, <code>reports</code>, <code>links</code> (live reverse connections), and per-agent <code>queues</code> are <code>BTreeMap</code>s.</p><p><strong>Implementation status:</strong> <code>inject</code>/<code>rollback</code> validate, archive a report stub, and then dispatch for real — a live link receives the command immediately, the agent&#39;s execution result is returned to the waiting controller (bounded by <code>DEFAULT_DISPATCH_TIMEOUT</code>, 5 s) and folded into the archived report; if the agent is offline the command persists in its queue and is drained on its next registration. <code>list_agents</code> annotates each <code>AgentIdentity.online</code> from link liveness or heartbeat freshness (<code>HEARTBEAT_TIMEOUT_MS</code>, 30 s) and offline agents are excluded from <code>available</code>.</p><h2 id="failure-handling-in-the-netem-adapter" tabindex="-1">Failure handling in the netem adapter <a class="header-anchor" href="#failure-handling-in-the-netem-adapter" aria-label="Permalink to “Failure handling in the netem adapter”">​</a></h2><ol><li><code>plan()</code> validates and returns the command list without executing.</li><li><code>inject()</code> runs a preflight <code>tc qdisc show</code> — refuses to touch an interface whose root qdisc is not FaultDeck&#39;s <code>100:</code> handle.</li><li>Any leftover FaultDeck root qdisc is cleaned up before applying.</li><li>If any command fails mid-apply, the adapter immediately issues the rollback command.</li><li><code>rollback()</code> deletes the root qdisc; &quot;not found&quot;-style <code>tc</code> errors are tolerated (idempotent).</li></ol><p>Disconnect faults bypass <code>tc</code> entirely — see <a href="/faultdeck/netem-faults.html#disconnect">Netem Faults</a>.</p><h2 id="source-layer-map" tabindex="-1">Source layer map <a class="header-anchor" href="#source-layer-map" aria-label="Permalink to “Source layer map”">​</a></h2><p>The source responsibility layers are independent of crate-directory names. Terms are synchronized in the <a href="/faultdeck/glossary.html">Glossary</a>.</p><h3 id="_1-shared-semantics-and-safety-model" tabindex="-1">1. Shared semantics and safety model <a class="header-anchor" href="#_1-shared-semantics-and-safety-model" aria-label="Permalink to “1. Shared semantics and safety model”">​</a></h3><p><code>crates/core/src/lib.rs</code> owns <code>FaultSpec</code>, <code>Target</code>, <code>Injection</code>, intrinsic validation, and management-network overlap checks (<code>crates/core/src/lib.rs:26</code>, <code>crates/core/src/lib.rs:44</code>, <code>crates/core/src/lib.rs:82</code>, <code>crates/core/src/lib.rs:108</code>, <code>crates/core/src/lib.rs:142</code>). It is persistent-state-free and has no network I/O. Its schema is Rust Serde plus the intrinsic validation errors at <code>crates/core/src/lib.rs:88</code>; fault-facing prose is in <a href="/faultdeck/netem-faults.html">Netem Faults</a>, and no dedicated protocol file exists.</p><h3 id="_2-policy-to-backend-translation" tabindex="-1">2. Policy-to-backend translation <a class="header-anchor" href="#_2-policy-to-backend-translation" aria-label="Permalink to “2. Policy-to-backend translation”">​</a></h3><p><code>crates/netem/src/lib.rs</code> translates validated latency/loss into ordered <code>tc qdisc</code> and <code>filter</code> commands through <code>NetemAdapter</code> (<code>crates/netem/src/lib.rs:172</code>, <code>crates/netem/src/lib.rs:199</code>, <code>crates/netem/src/lib.rs:204</code>). Its execution port is <code>CommandExecutor</code> (<code>crates/netem/src/lib.rs:73</code>), the command schema is <code>TcCommand</code> (<code>crates/netem/src/lib.rs:56</code>), and runtime inputs are the interface name plus the optional dry-run executor setting (<code>crates/netem/src/lib.rs:172</code>, <code>crates/netem/src/lib.rs:80</code>). It stores no state between calls and exposes no network protocol; implementation detail is in <a href="/faultdeck/architecture.html#failure-handling-in-the-netem-adapter">Architecture</a>.</p><h3 id="_3-host-execution-and-guard" tabindex="-1">3. Host execution and guard <a class="header-anchor" href="#_3-host-execution-and-guard" aria-label="Permalink to “3. Host execution and guard”">​</a></h3><p><code>crates/agent/src/lib.rs</code> is the agent host: it accepts TCP, authenticates, guards management CIDRs, decodes requests, routes disconnect or netem, and keeps the active-fault marker in <code>Arc&lt;Mutex&lt;HashSet&lt;String&gt;&gt;&gt;</code> (<code>crates/agent/src/lib.rs:171</code>, <code>crates/agent/src/lib.rs:326</code>, <code>crates/agent/src/lib.rs:340</code>). Its config schema is <code>AgentConfig</code> (<code>crates/agent/src/lib.rs:90</code>), populated by <code>crates/agent/src/main.rs:9</code>; <a href="/faultdeck/configuration.html">Configuration</a> documents those inputs. The <code>Iptables</code> backend in <code>crates/agent/src/firewall.rs:31</code> executes host rules, while protocol types remain in <code>crates/agent/src/lib.rs:109</code> and <code>crates/agent/src/lib.rs:117</code>; no dedicated protocol file exists.</p><h3 id="_4-wire-transport-and-topology" tabindex="-1">4. Wire transport and topology <a class="header-anchor" href="#_4-wire-transport-and-topology" aria-label="Permalink to “4. Wire transport and topology”">​</a></h3><p><code>crates/agent/src/transport.rs</code> owns bounded NDJSON framing plus Mode A listen/accept and Mode B reverse connect (<code>crates/agent/src/transport.rs:56</code>, <code>crates/agent/src/transport.rs:94</code>, <code>crates/agent/src/transport.rs:118</code>). It is stateless except accepted sockets. The framing schema is the generic <code>send_frame</code>/<code>read_frame</code> pair (<code>crates/agent/src/transport.rs:57</code>, <code>crates/agent/src/transport.rs:65</code>). On top of that framing, <code>crates/agent/src/link.rs</code> implements the live Mode B link session — register envelope, heartbeat thread, dispatch pump, and the reconnecting <code>run_link</code> loop (<code>crates/agent/src/link.rs:77</code>, <code>crates/agent/src/link.rs:140</code>, <code>crates/agent/src/link.rs:184</code>). Topology prose is in <a href="/faultdeck/remote-agents.html">Agents</a>, and payload types live in the agent and coordinator layers rather than a dedicated protocol crate (<code>crates/protocol/src</code> is empty).</p><h3 id="_5-user-boundary-and-report-materialization" tabindex="-1">5. User boundary and report materialization <a class="header-anchor" href="#_5-user-boundary-and-report-materialization" aria-label="Permalink to “5. User boundary and report materialization”">​</a></h3><p><code>crates/cli/src/main.rs</code> converts <code>remote ping/inject/rollback</code> and <code>hub list/inject/rollback</code> arguments into shared <code>Injection</code> values, performs bounded TCP exchanges with the agent or coordinator, optionally materializes JSON/HTML reports, and generates a replay command (<code>crates/cli/src/main.rs:136</code>, <code>crates/cli/src/main.rs:165</code>, <code>crates/cli/src/main.rs:227</code>, <code>crates/cli/src/main.rs:341</code>). It owns no server state; file output is caller-directed. The command schema is the clap tree at <code>crates/cli/src/main.rs:22</code>, <code>FAULTDECK_TIMEOUT_SECS</code> is the sole environment input (<code>crates/cli/src/main.rs:236</code>), and user-facing flags are documented in <a href="/faultdeck/configuration.html">Configuration</a>.</p><h3 id="_6-fleet-registry-and-control-plane-state" tabindex="-1">6. Fleet registry and control-plane state <a class="header-anchor" href="#_6-fleet-registry-and-control-plane-state" aria-label="Permalink to “6. Fleet registry and control-plane state”">​</a></h3><p><code>crates/coordinator/src/lib.rs</code> runs a threaded TCP hub, stores agents, reports, live links, and per-agent queues in <code>Arc&lt;Mutex&lt;CoordinatorState&gt;&gt;</code>, and handles controller sessions plus agent reverse links (<code>crates/coordinator/src/lib.rs:156</code>, <code>crates/coordinator/src/lib.rs:270</code>, <code>crates/coordinator/src/lib.rs:455</code>, <code>crates/coordinator/src/lib.rs:503</code>). All state is volatile. <code>AgentIdentity</code>, <code>AgentCommand</code>, <code>AgentResponse</code>, and <code>WireMessage</code> define that schema (<code>crates/coordinator/src/lib.rs:51</code>, <code>crates/coordinator/src/lib.rs:69</code>, <code>crates/coordinator/src/lib.rs:80</code>, <code>crates/coordinator/src/lib.rs:235</code>); <code>crates/coordinator/src/main.rs:4</code> supplies bind/token inputs documented in <a href="/faultdeck/configuration.html">Configuration</a>. <a href="/faultdeck/remote-agents.html">Agents</a> carries the operational protocol prose.</p><h3 id="_7-evidence-and-reproducibility-model" tabindex="-1">7. Evidence and reproducibility model <a class="header-anchor" href="#_7-evidence-and-reproducibility-model" aria-label="Permalink to “7. Evidence and reproducibility model”">​</a></h3><p><code>crates/report/src/lib.rs</code> owns <code>Scenario</code>, scenario hashing, <code>RunReport</code>, HTML rendering, timestamps, and report comparison (<code>crates/report/src/lib.rs:38</code>, <code>crates/report/src/lib.rs:49</code>, <code>crates/report/src/lib.rs:78</code>, <code>crates/report/src/lib.rs:110</code>, <code>crates/report/src/lib.rs:168</code>, <code>crates/report/src/lib.rs:182</code>). It is persistent-state-free; CLI and coordinator decide whether to retain output. Its Serde schema is the report model itself, HTML copy is generated in the same layer, and dedicated user prose is in <a href="/faultdeck/reports.html">Reports</a>.</p><h3 id="why-these-layers-are-split" tabindex="-1">Why these layers are split <a class="header-anchor" href="#why-these-layers-are-split" aria-label="Permalink to “Why these layers are split”">​</a></h3><ol><li><code>core::Injection</code> is consumed by both direct CLI construction and coordinator validation, so semantic validation must not depend on either transport host (<code>crates/cli/src/main.rs:136</code>, <code>crates/coordinator/src/lib.rs:309</code>).</li><li>Netem exposes plan, inject, and rollback separately; the agent needs execution while adapters and tests need dry planning or recorded commands (<code>crates/netem/src/lib.rs:199</code>, <code>crates/netem/src/lib.rs:204</code>, <code>crates/netem/src/lib.rs:232</code>).</li><li>The netem executor is a trait so the same command translation can target Linux <code>tc</code>, dry-run, or a test recorder without changing policy (<code>crates/netem/src/lib.rs:73</code>, <code>crates/netem/src/lib.rs:163</code>).</li><li>Disconnect and packet faults differ in state, atomicity, and rollback mechanics; the agent routes them to separate <code>Iptables</code> and <code>NetemAdapter</code> implementations (<code>crates/agent/src/lib.rs:196</code>, <code>crates/agent/src/firewall.rs:117</code>, <code>crates/netem/src/lib.rs:204</code>).</li><li>The agent&#39;s active-fault marker lives across connections, but the command executor socket handle is accepted per connection; mixing those lifetimes would make recovery state accidental (<code>crates/agent/src/lib.rs:340</code>, <code>crates/agent/src/lib.rs:341</code>).</li><li>Coordinator state and dispatch routing are centralized separately from target execution: the hub turns a controller command into a <code>LinkMessage::Dispatch</code> on the agent&#39;s reverse channel (or queues it while the agent is offline), while the agent crate owns actual fault application (<code>crates/coordinator/src/lib.rs:351</code>, <code>crates/coordinator/src/lib.rs:660</code>).</li><li>Reports require stable hashes, replay text, and evidence fields independent of whether the caller stores them in a file or coordinator memory (<code>crates/report/src/lib.rs:49</code>, <code>crates/report/src/lib.rs:92</code>, <code>crates/cli/src/main.rs:233</code>).</li></ol>`,35)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};